import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.RZAa07QS.js";const u=JSON.parse('{"title":"Sprint 7 — Social OAuth & Token Management","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_07_Social_OAuth_Token_Management.md","filePath":"plan/sprints/Sprint_07_Social_OAuth_Token_Management.md"}'),i={name:"plan/sprints/Sprint_07_Social_OAuth_Token_Management.md"};function r(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="sprint-7-—-social-oauth-token-management" tabindex="-1">Sprint 7 — Social OAuth &amp; Token Management <a class="header-anchor" href="#sprint-7-—-social-oauth-token-management" aria-label="Permalink to &quot;Sprint 7 — Social OAuth &amp; Token Management&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 13–14 (Aug 12–25, 2026) <strong>Jira:</strong> DA Sprint 7 <strong>Phase:</strong> Phase 4 — Social Integration &amp; AI Pipeline <strong>Goal:</strong> Implement OAuth connection flows for all 5 social platforms (Facebook, Instagram, TikTok, Threads, Zalo OA), encrypt and store tokens securely, and set up automated token lifecycle management.</p><p>&gt; <strong>AI Parallel:</strong> AI Iteration 2 runs concurrently this sprint.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E18</td><td>Meta OAuth (Facebook + Instagram)</td><td>Phước, Trung</td></tr><tr><td>E19</td><td>TikTok, Threads &amp; Zalo OA OAuth</td><td>Phước, Trung</td></tr><tr><td>E20</td><td>Token Lifecycle Management</td><td>Trung, Phước</td></tr></tbody></table><p><strong>Deliverables by end of Sprint 7:</strong></p><ul><li>All 5 platform OAuth flows working (FB, IG, TikTok, Threads, Zalo OA)</li><li>All tokens AES-256 encrypted before storage</li><li>Token status dashboard API working</li><li>Scheduled token refresh job running at 2:00 AM daily</li><li>Alert notifications on token refresh failure</li></ul><hr><h2 id="epic-e18-—-meta-oauth-facebook-instagram" tabindex="-1">EPIC E18 — Meta OAuth (Facebook + Instagram) <a class="header-anchor" href="#epic-e18-—-meta-oauth-facebook-instagram" aria-label="Permalink to &quot;EPIC E18 — Meta OAuth (Facebook + Instagram)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E18-01</td><td>Implement Facebook Fanpage OAuth flow (redirect → callback → token exchange)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E18-02</td><td>Implement Instagram Business account connection (linked via Facebook Business)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E18-03</td><td>Implement AES-256 encryption for access token + refresh token before saving to MongoDB</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E18-04</td><td>Implement disconnect flow (revoke token at Meta, remove from MongoDB)</td><td>Phước (Publisher)</td><td>🟡 High</td></tr></tbody></table><p><strong>Facebook OAuth flow (DA-E18-01):</strong></p><ol><li>Frontend redirects to <code>https://www.facebook.com/dialog/oauth?client_id=...&amp;scope=pages_manage_posts,pages_read_engagement</code></li><li>Meta redirects back to <code>/api/v1/social/facebook/callback?code=...</code></li><li>Exchange code for user access token → exchange for long-lived page access token (60 days)</li><li>Encrypt token with AES-256 → store in <code>social_accounts</code> collection</li></ol><p><strong>Instagram (DA-E18-02):</strong> Instagram Business requires a linked Facebook Page. Reuse FB page token + call <code>/me/accounts</code> → get IG business account ID.</p><p><strong>AES-256 encryption (DA-E18-03):</strong></p><ul><li>Key: 256-bit key from environment variable <code>SOCIAL_TOKEN_ENCRYPTION_KEY</code></li><li>Algorithm: AES-256-GCM (provides authentication)</li><li>Store: encrypted bytes + IV in MongoDB. Decrypt only when needed for publishing.</li></ul><hr><h2 id="epic-e19-—-tiktok-threads-zalo-oa-oauth" tabindex="-1">EPIC E19 — TikTok, Threads &amp; Zalo OA OAuth <a class="header-anchor" href="#epic-e19-—-tiktok-threads-zalo-oa-oauth" aria-label="Permalink to &quot;EPIC E19 — TikTok, Threads &amp; Zalo OA OAuth&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E19-01</td><td>Implement TikTok for Business OAuth (Client Credentials Flow)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E19-02</td><td>Implement Threads OAuth (using Meta Graph API, scope: threads_basic + threads_content_publish)</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E19-03</td><td>Implement Zalo Official Account OAuth</td><td>Phước (Publisher)</td><td>🔴 Critical</td></tr><tr><td>DA-E19-04</td><td>Implement token status dashboard API (view ACTIVE/EXPIRED/REVOKED status for all accounts)</td><td>Trung (Leader)</td><td>🟡 High</td></tr></tbody></table><p><strong>TikTok OAuth (DA-E19-01):</strong></p><ul><li>Use TikTok for Business API — requires app review for <code>video.publish</code> scope</li><li>OAuth 2.0 Authorization Code flow</li><li>Token lifetime: access token 24h, refresh token 365 days</li></ul><p><strong>Zalo OA (DA-E19-03):</strong></p><ul><li>Zalo OA SDK / REST API</li><li>Requires registered Zalo Official Account (not personal)</li><li>Token lifetime: access token 1h, refresh token 90 days — most aggressive refresh schedule</li></ul><p><strong>Token status API (DA-E19-04):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/social/accounts</span></span>
<span class="line"><span>Response: [{platform, accountName, status: ACTIVE|EXPIRING_SOON|EXPIRED|REVOKED, expiresAt}]</span></span></code></pre></div><hr><h2 id="epic-e20-—-token-lifecycle-management" tabindex="-1">EPIC E20 — Token Lifecycle Management <a class="header-anchor" href="#epic-e20-—-token-lifecycle-management" aria-label="Permalink to &quot;EPIC E20 — Token Lifecycle Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E20-01</td><td>Implement scheduled token refresh job (runs at 2:00 AM daily, refresh tokens expiring within 7 days)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E20-02</td><td>Implement alert notification when token refresh fails (notify Account Manager)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E20-03</td><td>Implement manual token refresh API (Account Manager triggers refresh manually)</td><td>Phước (Publisher)</td><td>🟡 High</td></tr></tbody></table><p><strong>Token refresh schedule (DA-E20-01):</strong></p><ul><li>Run at 2:00 AM workspace local timezone (use workspace.timezone setting)</li><li>Query <code>social_accounts</code> where <code>tokenExpiresAt &lt; now + 7 days</code></li><li>Per platform refresh logic: <ul><li>Facebook: exchange long-lived token for new one (if &lt; 60 days remaining)</li><li>TikTok: use refresh token to get new access token</li><li>Threads: same as Facebook (Meta API)</li><li>Zalo OA: must refresh every 1h — use a separate 45-min job</li><li>Instagram: tied to Facebook</li></ul></li></ul><p><strong>Notes:</strong></p><ul><li>Zalo OA 1-hour token TTL means a separate 45-minute refresh interval job is needed. Consider storing the refresh token separately with its own 90-day expiry check.</li><li>DA-E20-02 alert: create a notification record + send FCM push (if mobile) + in-app notification. Email optional.</li></ul><hr><h2 id="sprint-7-checklist" tabindex="-1">Sprint 7 Checklist <a class="header-anchor" href="#sprint-7-checklist" aria-label="Permalink to &quot;Sprint 7 Checklist&quot;">​</a></h2><ul><li>[ ] Facebook Fanpage OAuth: connect → page access token encrypted → stored</li><li>[ ] Instagram Business: connected via Facebook Business page</li><li>[ ] AES-256-GCM encryption: tokens encrypted at rest, decrypt only for publish</li><li>[ ] Facebook disconnect: token revoked at Meta, removed from DB</li><li>[ ] TikTok OAuth: access token + refresh token stored</li><li>[ ] Threads OAuth: connected via Meta Graph API</li><li>[ ] Zalo OA OAuth: access token stored, 45-min refresh job configured</li><li>[ ] Token status dashboard: all 5 platforms show correct status</li><li>[ ] Daily 2:00 AM refresh job runs, refreshes tokens expiring within 7 days</li><li>[ ] Failed refresh: Account Manager receives in-app alert</li><li>[ ] Manual refresh API: Account Manager can trigger on demand</li></ul>`,35)])])}const k=t(i,[["render",r]]);export{u as __pageData,k as default};
